export function getAyatFadilaBySection(section: AyatFadilaSection): QuranicVirtueItem[] {
  return AYAT_FADILA_ITEMS.filter((item) => item.section === section);
}

export function getAyatFadilaById(id: string): QuranicVirtueItem | undefined {
  return AYAT_FADILA_ITEMS.find((item) => item.id === id);
}

export function searchAyatFadila(query: string, section?: AyatFadilaSection): QuranicVirtueItem[] {
  const q = (query || '').trim();
  let list = AYAT_FADILA_ITEMS as readonly QuranicVirtueItem[];
  if (section) {
    list = list.filter((item) => item.section === section);
  }
  if (!q) return [...list];

  // Strip Tashkeel/Harakat for accurate Arabic matching
  const normalizeAr = (s: string) =>
    s.replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g, '').toLowerCase();

  // Strip Latin accents for robust French/English search
  const normalizeLatin = (s: string) =>
    s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

  const normQAr = normalizeAr(q);
  const normQLatin = normalizeLatin(q);

  return list.filter((item) => {
    return (
      item.id.toLowerCase().includes(normQLatin) ||
      normalizeAr(item.titleAr).includes(normQAr) ||
      normalizeAr(item.surahNameAr).includes(normQAr) ||
      normalizeAr(item.virtueAr).includes(normQAr) ||
      normalizeAr(item.arabic).includes(normQAr) ||
      normalizeLatin(item.titleFr).includes(normQLatin) ||
      normalizeLatin(item.surahNameFr).includes(normQLatin) ||
      normalizeLatin(item.virtueFr).includes(normQLatin) ||
      normalizeLatin(item.titleEn).includes(normQLatin) ||
      normalizeLatin(item.surahNameEn).includes(normQLatin) ||
      normalizeLatin(item.virtueEn).includes(normQLatin) ||
      normalizeLatin(item.reference).includes(normQLatin)
    );
  });
}
